custom_css:
/* =====================================================================
   SillyTavern Redesign — theme stylesheet
   ---------------------------------------------------------------------
   Ships as the `custom_css` field of "SillyTavern Redesign.json".
   Edit THIS file, then run `node build.mjs` to regenerate the JSON.

   Route A from the design notes: colour, type, radius, spacing, the left
   rail, the docked sheets, chat bubbles, the composer pill and the
   character grid — all reachable without touching SillyTavern's code.

   Injected as <style id="custom-style"> at the end of <head>, so it wins
   ties against every stylesheet SillyTavern links. !important is only
   used where upstream already used it.
   ===================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@200;300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

/* ---------------------------------------------------------------------
   1. Tokens
   ------------------------------------------------------------------ */

:root {
    /* Surfaces, darkest to lightest */
    --st-bg: #08080a;
    /* page */
    --st-sheet: #0b0b0d;
    /* settings sheet, overlay pages */
    --st-well: #101013;
    /* code blocks, textareas, read-only wells */
    --st-card: #131316;
    /* panel + card surface */
    --st-user-mes: #141417;
    /* your bubble */
    --st-line: #17171b;
    /* hairline divider */
    --st-bot-mes: #1a1a1e;
    /* character bubble, inset control */
    --st-inset: #1a1a1e;
    --st-selected: #22222a;
    /* selected chip / segment */
    --st-track: #232329;
    /* slider track */
    --st-rail-active: #191920;
    /* active rail slot */

    /* Text, brightest to dimmest */
    --st-text: #e8e8ea;
    --st-text-2: #dcdce0;
    --st-text-3: #c4c4cb;
    --st-text-4: #9a9aa4;
    --st-muted: #7c7c85;
    --st-faint: #5c5c64;
    --st-fainter: #4e4e56;

    /* The single accent */
    --st-accent: #9aa8e0;
    --st-accent-hover: #b9c3ee;
    --st-accent-fill: #7f8bc4;
    --st-accent-thumb: #cfd4ea;
    --st-accent-on: #3d4470;
    /* toggle track, "on" */
    --st-accent-knob: #dfe3f4;
    --st-accent-solid: #2b2f4a;
    /* primary button */

    /* Status */
    --st-ok: #4ade80;
    --st-warn-bg: #1c1a15;
    --st-warn-fg: #c9b989;
    --st-danger: #d08f9a;
    --st-danger-bg: #2a1c20;

    /* Geometry */
    --st-radius: 18px;
    /* card */
    --st-radius-sm: 12px;
    /* control */
    --st-radius-xs: 8px;
    --st-radius-pill: 999px;
    --st-rail-width: 68px;
    --st-rail-slot: 40px;
    --st-sheet-width: 452px;
    --st-content-max: 820px;
    /* message column */
    --st-composer-max: 720px;
    --st-composer-height: 46px;
    /* Half the single-line height: renders as a pill on one line, and stays
       a rounded rectangle as the field grows instead of curving into the
       text. A literal 999px would clamp to half of whatever the height
       becomes, which is what eats the first and last characters. */
    --st-composer-radius: 23px;
    --st-editor-max: 980px;
    /* character editor, advanced definitions */
    --st-wi-title-row: 42px;
    /* height of a World Info entry's title row */
    --st-bar-height: 62px;
    /* mobile bottom bar */

    /* Type */
    --mainFontFamily: 'Outfit', 'Noto Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
    --monoFontFamily: 'JetBrains Mono', 'Noto Sans Mono', ui-monospace, Consolas, monospace;

    /* Avatars are round in this system — that comes from avatar_style: 0, not
       from --avatar-base-border-radius, which upstream uses as a border WIDTH
       and margin (a percentage there breaks .add_avatar). Only the size moves. */
    --avatar-base-width: 38px;
    --avatar-base-height: 38px;

    /* Borders are replaced by surface contrast */
    --interactable-outline-color: var(--st-accent);
    --interactable-outline-color-faint: #2b2b32;
}

/* ---------------------------------------------------------------------
   2. Global
   ------------------------------------------------------------------ */

/* SillyTavern puts `transform: translateZ(0)` on <html> as a Chrome blur fix,
   which makes <html> — not the viewport — the containing block for every
   position:fixed element. On narrow screens <body> goes out of flow, <html>
   collapses to 0, and anything anchored to `bottom` lands off-screen. Giving
   <html> the viewport height restores it. */
html {
    height: 100dvh;
}

body {
    background-color: var(--st-bg);
    font-weight: 400;
    letter-spacing: 0;
}

/* No text shadows anywhere in this system. */
*,
.mes_text,
#chat {
    text-shadow: none !important;
}

a,
.mes_text a {
    color: var(--st-accent);
    text-decoration: none;
}

a:hover,
.mes_text a:hover {
    color: var(--st-accent-hover);
}

/* Upstream paints <hr> as a body-coloured gradient fade, which reads as a
   bright bar here. Dividers are hairlines in this system. */
hr {
    border: 0;
    border-top: 1px solid var(--st-line);
    background-image: none;
    background-color: transparent;
    height: 0;
    margin: 14px 0;
}

/* Scrollbars: thin, unobtrusive, no track. */
* {
    scrollbar-width: thin;
    scrollbar-color: #26262b transparent;
}

::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track,
body ::-webkit-scrollbar-track {
    background: transparent;
    border: 0;
    box-shadow: none;
}

::-webkit-scrollbar-thumb,
body ::-webkit-scrollbar-thumb {
    background: #26262b;
    border-radius: 8px;
    border: 0;
    box-shadow: none;
}

::-webkit-scrollbar-thumb:hover {
    background: #34343b;
}

/* The design is a flat near-black surface; the wallpaper stays out of it.
   To bring your background image back, delete this rule and set
   `#chat { background-color: transparent }` in your own Custom CSS. */
#bg1,
#bg_custom {
    display: none;
}

/* ---------------------------------------------------------------------
   3. Left rail  (#top-settings-holder)
   ------------------------------------------------------------------ */

/* The strip behind the old top bar has no place in this layout. */
#top-bar {
    display: none;
}

@media screen and (min-width: 1001px) {

    #top-settings-holder {
        position: fixed;
        top: 0;
        left: 0;
        bottom: 0;
        width: var(--st-rail-width);
        height: 100dvh;
        margin: 0;
        padding: 14px 0;
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
        gap: 14px;
        background-color: var(--st-bg);
        z-index: 3005;
    }

    #top-settings-holder>.drawer {
        width: auto;
        flex: none;
    }

    /* Rail order — mirrors the mock top to bottom. User Settings is given
       its own position at the foot. */
    #ai-config-button {
        order: 1;
    }

    #sys-settings-button {
        order: 2;
    }

    #advanced-formatting-button {
        order: 3;
    }

    #WI-SP-button {
        order: 4;
    }

    #rightNavHolder {
        order: 5;
    }

    #persona-management-button {
        order: 6;
    }

    #backgrounds-button {
        order: 7;
    }

    #extensions-settings-button {
        order: 8;
    }

    #user-settings-button {
        order: 9;
        margin-top: auto;
    }
}

#top-settings-holder .drawer-toggle {
    display: flex;
}

#top-settings-holder .drawer-icon {
    width: var(--st-rail-slot);
    height: var(--st-rail-slot);
    display: grid;
    place-items: center;
    padding: 0;
    font-size: 17px;
    border-radius: var(--st-radius-sm);
    color: var(--st-muted);
    opacity: 1;
    transition:
        background-color var(--animation-duration-2x),
        color var(--animation-duration-2x);
}

#top-settings-holder .drawer-icon:hover {
    background-color: #131316;
    color: var(--st-text-3);
    opacity: 1;
}

#top-settings-holder .drawer-icon.openIcon {
    background-color: var(--st-rail-active);
    color: var(--st-text-2);
}

/* Connection status dot, as in the mock. */
#top-settings-holder #API-status-top {
    position: relative;
}

#top-settings-holder #API-status-top.fa-plug::after {
    content: '';
    position: absolute;
    top: 5px;
    right: 5px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background-color: var(--st-ok);
}

/* ---------------------------------------------------------------------
   4. Docked settings sheet  (.drawer-content)
   ------------------------------------------------------------------ */

@media screen and (min-width: 1001px) {

    #top-settings-holder .drawer-content {
        position: fixed;
        top: 0;
        bottom: 0;
        left: var(--st-rail-width);
        right: auto;
        width: var(--st-sheet-width);
        min-width: 0;
        max-width: none;
        max-height: 100dvh;
        margin: 0;
        padding: 20px 20px 0;
        border: 0;
        border-radius: 0;
        background-color: var(--st-sheet);
        box-shadow: 34px 0 60px -20px rgba(0, 0, 0, .8);
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        z-index: 3000;
    }

    #top-settings-holder .drawer-content.openDrawer {
        display: flex;
        flex-direction: column;
        height: 100dvh;
    }

    /* Character management is a full page in this design, not a sheet. */
    #top-settings-holder #right-nav-panel {
        left: var(--st-rail-width);
        right: 0;
        width: calc(100dvw - var(--st-rail-width));
        background-color: var(--st-bg);
        box-shadow: none;
        padding: 22px 24px 0;
    }

    /* The grid wants the whole page; the editor is a reading column. */
    #right-nav-panel #rm_ch_create_block,
    #right-nav-panel #rm_PinAndTabs,
    #right-nav-panel #CharListButtonAndHotSwaps {
        max-width: var(--st-editor-max);
        margin-left: auto;
        margin-right: auto;
        width: 100%;
    }

    /* Advanced Definitions is a large centred dialog, not a takeover. */
    #character_popup {
        left: var(--st-rail-width);
        right: 0;
        top: 24px;
        width: auto;
        max-width: min(var(--st-editor-max), calc(100dvw - var(--st-rail-width) - 48px));
        height: calc(100dvh - 48px);
        min-height: 0;
        max-height: calc(100dvh - 48px);
    }

    /* Same footprint for the large editor. */
    .popup.wide_dialogue_popup,
    .popup.large_dialogue_popup {
        left: var(--st-rail-width);
        right: 0;
        margin-left: auto;
        margin-right: auto;
        width: min(var(--st-editor-max), calc(100dvw - var(--st-rail-width) - 48px));
        max-width: min(var(--st-editor-max), calc(100dvw - var(--st-rail-width) - 48px)) !important;
    }

    /* The character list is a full-width page of cards; the editor is a
       docked sheet like every other panel. Upstream shows one .right_menu at
       a time by writing an inline display, so that is the signal available. */
    #top-settings-holder #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) {
        left: var(--st-rail-width);
        right: auto;
        width: var(--st-sheet-width);
        background-color: var(--st-sheet);
        box-shadow: 34px 0 60px -20px rgba(0, 0, 0, .8);
        padding: 20px 20px 0;
    }

    /* --- Character list header -----------------------------------
       Upstream stacks the list button over the selected-character name in
       a flex column, and the pin sits in its own sub-column. Lay the panel
       out as a grid so all three read as one inline row at the left. */
    #top-settings-holder #right-nav-panel.openDrawer:not(:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"]))) {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        grid-template-rows: auto minmax(0, 1fr);
        align-items: start;
        align-content: start;
        column-gap: 14px;
    }

    /* start, not center: centring would float .scrollableInner in the
       middle of its 1fr row. Only the header pair centres. */
    #right-nav-panel #CharListButtonAndHotSwaps,
    #right-nav-panel #rm_PinAndTabs {
        align-self: center;
    }

    #right-nav-panel>.scrollableInner {
        align-self: stretch;
    }

    #right-nav-panel #CharListButtonAndHotSwaps {
        grid-row: 1;
        grid-column: 1;
        max-width: none;
        margin: 0;
        width: auto;
        align-items: center;
        gap: 10px;
    }

    #right-nav-panel #rm_PinAndTabs {
        grid-row: 1;
        grid-column: 2;
        max-width: none;
        margin: 0;
        width: auto;
    }

    #right-nav-panel>.scrollableInner {
        grid-row: 2;
        grid-column: 1 / -1;
    }

    /* The list button and the pin share a row rather than a column, and the
       pin comes out of the absolute top-right corner to join them. */
    #right-nav-panel #CharListButtonAndHotSwaps>.flexFlowColumn {
        flex-direction: row;
        align-items: center;
        gap: 10px;
        width: auto;
    }

    #right-nav-panel #rm_button_panel_pin_div {
        position: static;
        order: 2;
    }

    #right-nav-panel #rm_button_characters {
        order: 1;
    }

    /* Hotswaps are off in this theme; the empty wrapper still claims the row. */
    #right-nav-panel #HotSwapWrapper {
        width: auto;
        flex: 0 0 auto;
        margin: 0;
    }

    /* Upstream fades this block to 50%, which no colour on the <h2> can
       undo — opacity applies to the whole subtree. */
    #right-nav-panel #rm_button_selected_ch {
        opacity: 1;
    }

    #right-nav-panel #rm_button_selected_ch h2 {
        margin: 0;
        text-align: left;
        color: var(--st-text);
        font-weight: 400;
    }

    #right-nav-panel #right-nav-panel-tabs {
        align-items: center;
    }

    /* --- Character editor header ---------------------------------
       Sheet width wants a different arrangement from the full-width list:
       list button and pin pinned to opposite corners, then the character
       name on the left with its token counts on the right. */
    /* flex-grow only on the inner row. #CharListButtonAndHotSwaps is an item
       of the panel's COLUMN, so growing it eats the panel's vertical space
       and pushes the whole header into the middle of the sheet. */
    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #CharListButtonAndHotSwaps {
        width: 100%;
        flex: 0 0 auto;
        justify-content: space-between;
    }

    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #CharListButtonAndHotSwaps>.flexFlowColumn {
        width: 100%;
        flex: 1 1 auto;
        justify-content: space-between;
    }

    /* Upstream centres this block and lets it shrink to its content, which
       keeps the name and token counts bunched in the middle. */
    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #rm_PinAndTabs {
        align-self: stretch;
        width: 100%;
    }

    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #right-nav-panel-tabs {
        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        width: 100%;
    }

    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #rm_button_selected_ch {
        flex: 1 1 auto;
        min-width: 0;
    }

    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #rm_button_selected_ch h2 {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #result_info {
        flex: 0 0 auto;
        align-items: center;
        justify-content: flex-end;
        gap: 8px;
        text-align: right;
    }

    /* No reading-column cap once it is already sheet width. */
    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #rm_ch_create_block,
    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #rm_PinAndTabs,
    #right-nav-panel:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"])) #CharListButtonAndHotSwaps {
        max-width: 100%;
    }

    /* The sheets are children of #top-settings-holder, so their z-index is
       resolved inside the rail's own stacking context — at 3000 they paint
       over the rail as they slide past it. Repaint the rail on top: its
       background as a pseudo-element above the sheet, its icons above that.
       .drawer stays position:static so it forms no stacking context of its
       own and the sheet's 3000 keeps competing at this level. */
    #top-settings-holder::before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        bottom: 0;
        width: var(--st-rail-width);
        background-color: var(--st-bg);
        z-index: 3001;
        pointer-events: none;
    }

    #top-settings-holder .drawer-toggle {
        position: relative;
        z-index: 3002;
    }

    /* The character list is a full-width page, not a sheet — sweeping it in
       from the left reads as the whole app moving, so it just fades. The
       character editor is the same element in sheet form, and that one still
       slides like every other sheet; hence the :has() rather than a blanket
       rule on #right-nav-panel. */
    #top-settings-holder #right-nav-panel:not(:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"]))),
    #top-settings-holder #right-nav-panel:not(:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"]))).openDrawer {
        transform: none;
    }

    /* Upstream opens a drawer by animating height 0 -> auto, which reads as
       "unrolling downward". Docked to the left edge, that looks wrong — the
       sheet should come in from the side it lives on. Hold the height
       constant and animate the slide instead. display is transitioned with
       allow-discrete so the panel can still leave the layout when closed. */
    #top-settings-holder .drawer-content {
        height: 100dvh;
        transform: translateX(-100%);
        opacity: 0;
        transition-property: transform, opacity, display;
        transition-duration: var(--animation-duration-2x);
        transition-timing-function: ease;
        transition-behavior: allow-discrete;
    }

    #top-settings-holder .drawer-content.openDrawer {
        transform: translateX(0);
        opacity: 1;
    }

    @starting-style {
        #top-settings-holder .drawer-content.openDrawer {
            transform: translateX(-100%);
            opacity: 0;
        }
    }

    @starting-style {
        #top-settings-holder #right-nav-panel:not(:has(#rm_ch_create_block:not([style*="display: none"]):not([style*="display:none"]))).openDrawer {
            transform: none;
            opacity: 0;
        }
    }

    /* Free-dragging a docked sheet does not survive the dock. */
    #top-settings-holder .drag-grabber {
        display: none !important;
    }
}

#top-settings-holder .drawer-content>.scrollableInner,
#top-settings-holder .drawer-content>.scrollableInnerFull {
    flex: 1;
    min-height: 0;
    height: auto;
    padding: 0 4px 24px 0;
}

.fillLeft .scrollableInner {
    padding: 0 4px 24px 0;
}

/* --- Sheet header band ---------------------------------------------
   Each panel scatters a pin toggle, a help link and a caption around its
   top edge, all absolutely positioned and overlapping at this width.
   Reserve a band for them and lay them out. */

#top-settings-holder .drawer-content {
    padding-top: 54px;
}

/* No `display` here — mobile-styles.css hides these on small screens and
   that decision should stand. */
#lm_button_panel_pin_div,
#WI_panel_pin_div,
#rm_button_panel_pin_div {
    position: absolute;
    top: 15px;
    right: 52px;
    width: 32px;
    height: 32px;
    padding: 0;
    place-items: center;
    border-radius: 10px;
    background-color: var(--st-card);
    color: var(--st-muted);
    font-size: 13px;
    line-height: 32px;
    text-align: center;
    opacity: 1;
    z-index: 3;
}

#lm_button_panel_pin_div:hover,
#WI_button_panel_pin_div:hover,
#rm_button_panel_pin_div:hover {
    color: var(--st-text-3);
}

.topRightInset {
    top: 15px;
    right: 16px;
    width: 32px;
    height: 32px;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background-color: var(--st-card);
    z-index: 3;
}

.note-link-span {
    color: var(--st-muted);
    font-size: 13px;
    opacity: 1;
}

#clickSlidersTips,
.editable-slider-notification {
    position: absolute;
    top: 21px;
    left: 20px;
    right: 96px;
    width: auto;
    text-align: left;
    z-index: 2;
}

/* Panel headings: quiet, uppercase, letter-spaced. */
.drawer-content h3,
.drawer-content h4,
.drawer-content .standoutHeader,
.drawer-content .range-block-title>b,
.drawer-content>.scrollableInner>h4 {
    color: var(--st-text-4);
    font-weight: 400;
}

.drawer-content h4 {
    font-size: calc(var(--mainFontSize) * 0.75);
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--st-faint);
    margin: 18px 0 10px;
}

/* Upstream gives these a gradient plate with an accent corner; in this
   system a heading is just a heading.

   One declaration carries that gradient for four different selectors —
   .standoutHeader (0,1,0), #user-settings-block h4 (1,0,1) and two
   #extensions_settings ones (1,3,0) — so matching on specificity alone
   means chasing each of them. This kills the image outright on anything
   header-shaped, which also holds against extensions that copy the trick.
   The user's requirement here is absolute: never, anywhere. */
.standoutHeader,
.inline-drawer-header,
.inline-drawer-toggle,
#user-settings-block h4,
.drawer-content h3,
.drawer-content h4,
.drawer-content h5,
.popup h3,
.popup h4 {
    background-image: none !important;
}

.standoutHeader,
.standoutHeader.inline-drawer-header,
#user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    background-color: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    padding: 4px 0;
    margin-bottom: 4px;
}

/* Group headings come in two flavours upstream: an <h4> (User Settings) and
   a .standoutHeader div wrapping a <strong> (AI Response Configuration).
   They were reading as two different levels — small grey caps versus large
   bold white. One caption style for both. */
.drawer-content .standoutHeader>strong,
.drawer-content .standoutHeader>strong>span,
.drawer-content .standoutHeader>b,
.drawer-content .standoutHeader>span:first-child {
    font-size: calc(var(--mainFontSize) * 0.75);
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--st-faint);
    font-weight: 400;
}

.drawer-content .standoutHeader {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin: 18px 0 10px;
}

/* Label-and-control rows: one control column, aligned on both edges, rather
   than each select sizing to its own text. .widthNatural is
   `width: unset !important`, so the basis has to be !important too. */
#user-settings-block [name="AvatarAndChatDisplay"]>.flex-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 6px;
}

#user-settings-block [name="AvatarAndChatDisplay"]>.flex-container>span {
    flex: 0 1 auto;
    min-width: 0;
    color: var(--st-text-4);
}

#user-settings-block [name="AvatarAndChatDisplay"]>.flex-container>select {
    flex: 0 0 58% !important;
    width: 58% !important;
    min-width: 0 !important;
    max-width: 58% !important;
}

/* The panel title, the language picker and the version stamp fight for one
   row and clip the picker. Let them wrap. */
#user-settings-block [name="userSettingsRowOne"] {
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 12px;
}

#user-settings-block #UI-language-block {
    flex: 1 1 auto;
    min-width: 0;
    justify-content: flex-end;
    gap: 8px;
}

#user-settings-block #UI-language-block>select {
    flex: 0 1 auto;
    min-width: 110px;
    width: auto;
}

#user-settings-block #version_display {
    flex: 1 1 100%;
    text-align: left;
}

/* #user-settings-block h4 outranks the generic .drawer-content h4 styling. */
#user-settings-block h4 {
    font-size: calc(var(--mainFontSize) * 0.75);
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--st-faint);
    margin: 18px 0 10px;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
    background-image: none;
    background-color: transparent;
    color: var(--st-text);
}

/* The plate was what separated one extension from the next; the card does
   that job now. */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    padding: 12px 0;
}

.drawer-content h3 {
    font-size: calc(var(--mainFontSize) * 1.15);
    font-weight: 300;
    color: var(--st-text-4);
}

/* ---------------------------------------------------------------------
   5. Cards inside panels
   ------------------------------------------------------------------ */

.drawer-content .inline-drawer,
.drawer-content .settingsSectionWrap,
.drawer-content .standoutHeader~.inline-drawer-content,
#extensions_settings .inline-drawer,
#extensions_settings2 .inline-drawer {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-radius);
    padding: 4px 18px;
    margin-bottom: 12px;
}

.drawer-content .inline-drawer-header,
.drawer-content .inline-drawer-toggle {
    padding: 12px 0;
    font-size: calc(var(--mainFontSize) * 0.97);
    color: var(--st-text-2);
    font-weight: 400;
}

.drawer-content .inline-drawer-header b,
.drawer-content .inline-drawer-toggle b,
.drawer-content .inline-drawer-header strong {
    font-weight: 400;
}

.drawer-content .inline-drawer-icon {
    font-size: 11px;
    color: var(--st-muted);
    filter: none;
}

.drawer-content .inline-drawer-content {
    padding-bottom: 14px;
}

.drawer-content .inline-drawer .inline-drawer {
    background-color: var(--st-inset);
    border-radius: var(--st-radius-sm);
    padding: 2px 14px;
}

/* Hint / footnote text. */
.toggle-description,
.drawer-content small,
#clickSlidersTips,
.wi-enter-footer-text {
    color: var(--st-fainter);
    font-size: calc(var(--mainFontSize) * 0.78);
    line-height: 1.5;
    opacity: 1;
}

/* Callouts. */
.redWarningBG,
.warning,
#AdvancedFormatting .warning {
    background-color: var(--st-warn-bg) !important;
    color: var(--st-warn-fg) !important;
    border: 0;
    border-radius: var(--st-radius-sm);
    padding: 12px 15px;
    font-size: calc(var(--mainFontSize) * 0.83);
}

/* ---------------------------------------------------------------------
   6. Form controls
   ------------------------------------------------------------------ */

.text_pole,
select,
select.text_pole,
textarea,
input[type="text"],
input[type="number"],
input[type="search"],
input[type="password"] {
    background-color: var(--st-inset);
    color: var(--st-text-2);
    border: 1px solid transparent;
    border-radius: var(--st-radius-sm);
    padding: 8px 13px;
    font-family: var(--mainFontFamily);
    transition: border-color var(--animation-duration-2x);
}

select,
select.text_pole {
    height: 38px;
    padding-right: 28px;
    background-position: right 13px center;
}

.text_pole:focus-visible,
select:focus-visible,
textarea:focus-visible,
input:focus-visible {
    border-color: #2f2f38;
    outline: none;
}

.text_pole::placeholder,
textarea::placeholder {
    color: var(--st-fainter);
    opacity: 1;
}

select option {
    background-color: var(--st-card);
    color: var(--st-text-2);
}

/* Multi-line fields read as wells, not as inputs. */
textarea,
textarea.text_pole,
#send_textarea {
    background-color: var(--st-well);
    line-height: 1.6;
}

textarea.monospace,
.monospace,
code,
pre,
tt,
.mes_text code {
    font-family: var(--monoFontFamily);
    font-size: calc(var(--mainFontSize) * 0.82);
}

pre,
.mes_text pre {
    background-color: var(--st-well);
    border: 0;
    border-radius: var(--st-radius-sm);
    padding: 13px 15px;
}

.mes_text code:not(pre code) {
    background-color: var(--st-well);
    border-radius: 5px;
    padding: 1px 5px;
}

/* Buttons.
   No font-family here: many buttons carry their Font Awesome class on the
   button element itself (`class="menu_button fa-solid fa-save"`), so setting
   a font on .menu_button replaces the icon with a tofu box. */
.menu_button {
    background-color: var(--st-inset);
    color: var(--st-text-3);
    border: 0;
    border-radius: var(--st-radius-sm);
    padding: 8px 13px;
    filter: none;
    transition: background-color var(--animation-duration-2x), color var(--animation-duration-2x);
}

.menu_button:not(.disabled):not([disabled]):hover,
.menu_button:not(.disabled):not([disabled]).active {
    background-color: var(--st-selected);
    color: var(--st-text);
}

.menu_button.menu_button_icon {
    gap: 8px;
}

.menu_button.toggleable.toggled {
    background-color: var(--st-accent-solid);
    color: #e6e9f7;
}

/* The one solid, primary-coloured control per panel. */
#api_button,
#api_button_textgenerationwebui,
#api_button_novel,
.api_button {
    background-color: var(--st-accent-solid);
    color: #e6e9f7;
}

.right_menu_button,
.menu_button_icon i {
    color: var(--st-muted);
}

/* Checkboxes become pill toggles. */
.drawer-content input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox):not(#lm_button_panel_pin):not(#rm_button_panel_pin):not(#WI_panel_pin),
.popup input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox) {
    appearance: none;
    -webkit-appearance: none;
    position: relative;
    width: 40px;
    height: 22px;
    min-width: 40px;
    border: 0;
    outline: none;
    border-radius: var(--st-radius-pill);
    background-color: var(--st-track);
    box-shadow: none;
    filter: none;
    overflow: visible;
    transform: none;
    display: inline-block;
    transition: background-color var(--animation-duration-2x);
}

.drawer-content input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox):not(#lm_button_panel_pin):not(#rm_button_panel_pin):not(#WI_panel_pin)::before,
.popup input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox)::before {
    content: '';
    position: absolute;
    top: 3px;
    left: 3px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background-color: var(--st-faint);
    box-shadow: none;
    clip-path: none;
    transform: none;
    transition: left var(--animation-duration-2x), background-color var(--animation-duration-2x);
}

.drawer-content input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox):not(#lm_button_panel_pin):not(#rm_button_panel_pin):not(#WI_panel_pin):checked,
.popup input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox):checked {
    background-color: var(--st-accent-on);
}

.drawer-content input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox):not(#lm_button_panel_pin):not(#rm_button_panel_pin):not(#WI_panel_pin):checked::before,
.popup input[type="checkbox"]:not(.del_checkbox):not(.bulk_select_checkbox):checked::before {
    left: 21px;
    background-color: var(--st-accent-knob);
}

.checkbox_label,
label.checkbox_label {
    gap: 12px;
    align-items: center;
    color: var(--st-text-4);
    font-size: calc(var(--mainFontSize) * 0.87);
}

/* ---------------------------------------------------------------------
   7. Sliders
   ------------------------------------------------------------------ */

/* Label on the left, value on the right, full-width track underneath.

   SillyTavern's slider markup has no single wrapper class — some blocks use
   .range-block-range-and-counter, others are a bare .flex-container.
   The one reliable anchor is "the element that directly contains the range
   input", so that is what the layout hangs off. */

.drawer-content :has(> .neo-range-slider),
.popup :has(> .neo-range-slider) {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    /* !important because most of these blocks carry .gap0, which upstream
       declares as `gap: 0 !important` — without it the value sits directly
       on the track and the thumb rides into the digits. */
    column-gap: 10px !important;
    row-gap: 12px !important;
    margin-bottom: 24px;
}

.drawer-content :has(> .neo-range-slider)>small,
.drawer-content :has(> .neo-range-slider)>label,
.drawer-content :has(> .neo-range-slider)> span,
.popup :has(> .neo-range-slider)>small,
.popup :has(> .neo-range-slider)>label {
    grid-row: 1;
    grid-column: 1;
    justify-self: start;
    text-align: left;
    font-size: calc(var(--mainFontSize) * 0.84);
    color: var(--st-text-4);
    opacity: 1;
}

.drawer-content :has(> .neo-range-slider)>.neo-range-slider,
.popup :has(> .neo-range-slider)>.neo-range-slider {
    grid-row: 2;
    grid-column: 1 / -1;
    margin-top: 0 !important;
}

.drawer-content :has(> .neo-range-slider)>.neo-range-input,
.drawer-content :has(> .neo-range-slider)> :has(> .neo-range-input),
.popup :has(> .neo-range-slider)>.neo-range-input,
.popup :has(> .neo-range-slider)> :has(> .neo-range-input) {
    grid-row: 1;
    grid-column: 2;
    justify-self: end;
    width: auto;
    margin: 0;
}

/* Anything else the block carries (a streaming toggle, a hint) goes below. */
.drawer-content :has(> .neo-range-slider)> :not(small):not(label):not(span):not(.neo-range-slider):not(.neo-range-input):not(:has(> .neo-range-input)) {
    grid-column: 1 / -1;
}

/* The info tooltip icon that rides along with the label. */
.drawer-content :has(> .neo-range-slider)>small>.fa-circle-info {
    font-size: calc(var(--mainFontSize) * 0.7);
    margin-left: 5px;
    opacity: .5;
}

/* Slider groups sit directly on the panel, matching User Settings — the
   <hr> between groups carries the separation instead of a card. */
.drawer-content .flex-container.gap10h5v:has(> * > .neo-range-slider),
#pro-settings-block {
    background-color: transparent;
    border-radius: 0;
    padding: 0;
    margin-bottom: 4px;
    gap: 4px 20px;
}

/* Legacy .range-block wrapper. */
.range-block:has(> .range-block-range-and-counter) {
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas:
        "title counter"
        "range range";
    align-items: baseline;
    column-gap: 14px;
    row-gap: 10px;
    margin-bottom: 20px;
}

.range-block:has(> .range-block-range-and-counter)>.range-block-title {
    grid-area: title;
    width: auto;
    text-align: left;
    font-size: calc(var(--mainFontSize) * 0.87);
    color: var(--st-text-4);
}

.range-block:has(> .range-block-range-and-counter)>.range-block-range-and-counter {
    display: contents;
}

.range-block:has(> .range-block-range-and-counter) .range-block-range {
    grid-area: range;
    flex: none;
}

.range-block:has(> .range-block-range-and-counter) .range-block-counter {
    grid-area: counter;
    margin: 0;
    flex: none;
    justify-self: end;
}

/* Specificity has to clear the generic input[type="number"] rule above. */
.range-block-counter input[type="number"],
input.neo-range-input {
    background-color: transparent;
    border: 0;
    border-radius: var(--st-radius-xs) !important;
    color: var(--st-text-3);
    font-family: var(--monoFontFamily);
    font-size: calc(var(--mainFontSize) * 0.8);
    text-align: right;
    padding: 2px 6px;
    padding-left: 6px;
    width: 72px;
    height: auto;
}

.range-block-counter input[type="number"]:hover,
input.neo-range-input:hover {
    background-color: var(--st-inset);
}

/* A 452 px sheet has no room for the two- and three-up column classes the
   panels use at full width; one control per row instead. */
/* The panels that are laid out as columns at full width. mobile-styles.css
   already flattens these below 1000px; the docked sheet needs it always. */
#UI-Theme-Block,
#UI-Customization,
#power-user-options-block,
#ContextSettings,
#InstructSettingsColumn,
#InstructSequencesColumn {
    flex-basis: 100%;
    max-width: 100%;
}

/* Extensions register into two side-by-side .wide50p columns. At sheet width
   that halves every card and wraps the titles, so give each column the full
   row instead.

   Do NOT do this by turning .extensions_block into a flex column: the two
   blocks are .flex1, whose basis would then apply to their HEIGHT inside a
   height-bounded drawer, collapsing both to nothing and blanking the panel.
   Keeping the row and wrapping it keeps the basis on the width axis. */
#rm_extensions_block .extensions_block {
    flex-wrap: wrap;
}

#rm_extensions_block #extensions_settings,
#rm_extensions_block #extensions_settings2 {
    flex: 0 0 100%;
    width: 100%;
    max-width: 100%;
    min-width: 0;
}

/* --- Persona Management ------------------------------------------------
   Three rows here assume a wide panel and collide at sheet width: the title
   shares a line with three labelled buttons, the create row packs a button,
   a search field, a sort select, a pager and a view toggle onto one line,
   and the persona's action buttons wrap under its name. */

/* Title keeps its line; Usage Stats / Backup / Restore take the next. */
#PersonaManagement>.flex-container>.flex-container.alignItemsBaseline {
    flex-wrap: wrap;
    gap: 8px;
}

#PersonaManagement>.flex-container>.flex-container.alignItemsBaseline>.flex1 {
    flex: 1 1 100%;
}

#PersonaManagement>.flex-container>.flex-container.alignItemsBaseline>.flex-container {
    flex: 1 1 100%;
    flex-wrap: wrap;
    gap: 8px;
}

/* Create + search on one line, sort / pager / view toggle on the next. */
#persona-management-block .flex-container.marginBot10 {
    flex-wrap: wrap;
    gap: 8px;
}

#create_dummy_persona {
    flex: 0 0 auto;
    margin: 0;
}

#persona_search_bar {
    flex: 1 1 140px;
    min-width: 120px;
    width: auto;
}

#persona_sort_order {
    flex: 0 0 auto;
    min-width: 92px;
    width: auto;
    margin: 0;
}

/* Wide enough to break onto its own line, but still sharing it with the
   view toggle rather than stranding it below. */
#persona_pagination_container {
    flex: 1 1 200px;
    min-width: 0;
}

#persona_grid_toggle {
    flex: 0 0 auto;
    margin: 0;
}

/* Name and the More… picker share a line; the icon row gets its own. */
#persona_controls {
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

#persona_controls .persona_name {
    order: 1;
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
}

#persona_controls label[for="persona-management-dropdown"] {
    order: 2;
    flex: 0 1 auto;
    height: auto;
}

#persona_controls .persona_controls_buttons_block {
    order: 3;
    flex: 1 1 100%;
    flex-wrap: nowrap;
    justify-content: flex-start;
    gap: 6px;
}

#persona_controls .persona_controls_buttons_block .menu_button {
    flex: 0 1 auto;
    margin: 0;
}

/* Persona Management is a two-column layout that does not fit the sheet. */
#persona-management-block {
    flex-direction: column;
}

#persona-management-block>div {
    width: 100%;
    max-width: 100%;
    flex-basis: auto;
}

#rm_ch_create_block .flexBasis25p,
#rm_ch_create_block .flexBasis30p,
#rm_ch_create_block .flexBasis48p,
#rm_ch_create_block .flexBasis50p,
#rm_ch_create_block .flexBasis200px,
.drawer-content:not(#right-nav-panel) .flexBasis25p,
.drawer-content:not(#right-nav-panel) .flexBasis30p,
.drawer-content:not(#right-nav-panel) .flexBasis48p,
.drawer-content:not(#right-nav-panel) .flexBasis50p,
.drawer-content:not(#right-nav-panel) .flexBasis200px,
.drawer-content:not(#right-nav-panel) .drawer25pWidth,
.drawer-content:not(#right-nav-panel) .drawer33pWidth {
    flex-basis: 100%;
    max-width: 100%;
}

input[type="range"],
.neo-range-slider {
    height: 4px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: var(--st-track) !important;
    border-radius: var(--st-radius-pill) !important;
    box-shadow: none !important;
    filter: none !important;
    cursor: pointer !important;
}

input[type="range"]:hover,
.neo-range-slider:hover {
    filter: none !important;
    background: #2b2b32 !important;
}

input[type="range"]::-webkit-slider-thumb,
.neo-range-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 13px;
    height: 13px;
    border: 0;
    border-radius: 50%;
    background: var(--st-accent-thumb);
    box-shadow: none;
    cursor: pointer;
}

input[type="range"]::-moz-range-thumb,
.neo-range-slider::-moz-range-thumb {
    width: 13px;
    height: 13px;
    border: 0;
    border-radius: 50%;
    background: var(--st-accent-thumb);
}

input[type="range"]:hover::-webkit-slider-thumb,
.neo-range-slider:hover::-webkit-slider-thumb {
    background: #e6e9f7;
}

/* ---------------------------------------------------------------------
   8. Chat column
   ------------------------------------------------------------------ */

@media screen and (min-width: 1001px) {
    #sheld {
        left: var(--st-rail-width);
        right: 0;
        top: 0;
        width: calc(100dvw - var(--st-rail-width));
        height: 100dvh;
        max-height: 100dvh;
    }
}

#chat {
    background-color: var(--st-bg);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    max-height: none;
    /* the bottom value is breathing room between the last message and the
       composer — upstream forces .last_mes to margin-bottom: 0 */
    padding: 14px 24px 20px;
    gap: 4px;
}

#chat>.mes,
#chat>.welcomePanel {
    width: 100%;
    max-width: min(var(--st-content-max), var(--sheldWidth));
    margin-left: auto;
    margin-right: auto;
}

/* ---------------------------------------------------------------------
   9. Messages
   ------------------------------------------------------------------ */

.mes {
    color: var(--st-text-2);
    padding: 0;
    gap: 14px;
    margin-bottom: 14px;
}

.mes_text,
.mes_reasoning {
    font-weight: 400;
    line-height: 1.62;
}

.mes_text i,
.mes_text em {
    color: #8f8f98;
}

.mes_text q,
.mes_text q::before,
.mes_text q::after {
    color: var(--st-accent);
}

.mes .avatar,
.mes .avatar img {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    border: 0;
    box-shadow: none;
}

.mes .mes_block {
    padding-left: 0;
    min-width: 0;
}

.mes_block .ch_name {
    min-height: 0;
    font-size: calc(var(--mainFontSize) * 0.95);
    font-weight: 400;
    color: var(--st-text);
    margin-bottom: 6px;
}

.mes_block .ch_name .name_text {
    font-weight: 400;
}

.mes_buttons .mes_button,
.mes_buttons .extraMesButtonsHint {
    color: var(--st-faint);
    opacity: 1;
}

.mes_buttons .mes_button:hover {
    color: var(--st-text-3);
}

.timestamp,
.mes_timer,
.mesIDDisplay,
.tokenCounterDisplay {
    color: var(--st-fainter);
    font-family: var(--monoFontFamily);
    font-size: calc(var(--mainFontSize) * 0.65);
}

/* --- Bubbles ------------------------------------------------------- */

/* Upstream paints the bubble on .mes, which swallows the avatar.
   Move it onto .mes_block so the avatar sits outside, as in the mock. */
body.bubblechat #chat .mes {
    background-color: transparent;
    border: 0;
    border-radius: 0;
    padding: 0;
    margin-bottom: 18px;
    align-items: flex-start;
}

body.bubblechat #chat .mes .mes_block {
    background-color: var(--st-bot-mes);
    border-radius: 16px;
    padding: 13px 17px;
    width: auto;
    max-width: calc(100% - 52px);
    overflow: visible;
}

body.bubblechat #chat .mes[is_user="true"] {
    flex-direction: row-reverse;
}

/* The avatar is a flex sibling, so the bubble's cap leaves room for it. */
body.bubblechat #chat .mes[is_user="true"] .mes_block {
    background-color: var(--st-user-mes);
    max-width: min(78%, calc(100% - 52px));
    color: var(--st-text-3);
}

/* row-reverse puts the avatar on the trailing side, so your persona sits to
   the right of your own bubbles. */
body.bubblechat #chat .mes[is_user="true"] .mesAvatarWrapper {
    display: flex;
    flex-direction: column;
    align-items: center;
}

body.bubblechat #chat .mes .ch_name {
    margin-bottom: 5px;
    min-height: 0;
}

body.bubblechat #chat .mes:not(:hover) .mes_buttons {
    opacity: 0;
}

body.bubblechat #chat .mes .mes_buttons {
    transition: opacity var(--animation-duration-2x);
}

body.bubblechat .welcomePanel {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-radius);
    padding: 20px 24px;
}

/* --- Flat / document ----------------------------------------------- */

body:not(.bubblechat) #chat .mes {
    padding: 0 0 22px;
    border-bottom: 1px solid #131317;
    margin-bottom: 22px;
}

body:not(.bubblechat) #chat .mes.last_mes {
    border-bottom: 0;
}

/* Swipes. */
.swipe_left,
.swipe_right {
    color: var(--st-faint);
    opacity: 0;
    transition: opacity var(--animation-duration-2x);
}

.mes:hover .swipe_left,
.mes:hover .swipe_right,
.last_mes .swipe_left,
.last_mes .swipe_right {
    opacity: .6;
}

.swipes-counter {
    color: var(--st-fainter);
    font-family: var(--monoFontFamily);
    font-size: calc(var(--mainFontSize) * 0.62);
}

/* Reasoning block reads as a well, not a bubble-in-a-bubble. */
.mes_reasoning_details {
    background-color: var(--st-well);
    border: 0;
    border-radius: var(--st-radius-sm);
    padding: 10px 14px;
    margin-bottom: 10px;
}

.mes_reasoning_header_title {
    color: var(--st-muted);
    font-size: calc(var(--mainFontSize) * 0.8);
}

/* ---------------------------------------------------------------------
   10. Composer
   ------------------------------------------------------------------ */

#form_sheld {
    background: transparent;
    padding: 0 22px 18px;
}

/* toggle-dependent.css paints #send_form with !important under body.no-blur. */
#send_form,
body.no-blur #send_form {
    background: transparent !important;
    border: 0;
    border-radius: 0;
    backdrop-filter: none;
    justify-content: center;
}

#send_form:has(#send_textarea:focus-visible) {
    border-color: transparent;
    outline: none;
}

/* stretch, not center: the pill is two halves, and a centred right half
   stays 46px tall while the textarea grows, leaving the send button
   floating in a detached stub. */
#nonQRFormItems {
    max-width: calc(min(var(--st-composer-max), var(--sheldWidth)) + 54px);
    margin: 0 auto;
    align-items: stretch;
    column-gap: 0;
}

/* The options button sits outside the pill, on its own, level with the
   pill's last line once the field has grown. */
#leftSendForm {
    padding-left: 0;
    margin-right: 16px;
    align-self: flex-end;
    height: var(--st-composer-height);
    align-items: center;
}

#leftSendForm>div {
    color: var(--st-muted);
    opacity: 1;
}

#leftSendForm>div:hover {
    color: var(--st-text-3);
    filter: none;
}

/* The textarea and the right icon cluster are the two halves of one pill. */
#send_textarea {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-composer-radius) 0 0 var(--st-composer-radius);
    border-top: 0;
    clip-path: none;
    min-height: var(--st-composer-height);
    height: var(--st-composer-height);
    padding: 12px 4px 12px 20px;
    color: var(--st-text-2);
    line-height: 1.45;
}

#send_textarea::placeholder {
    color: var(--st-fainter) !important;
    text-align: start;
    opacity: 1;
}

/* Matches the textarea's height so the two halves stay one shape; the
   buttons ride the bottom line rather than the vertical middle. */
#rightSendForm {
    background-color: var(--st-card);
    border-radius: 0 var(--st-composer-radius) var(--st-composer-radius) 0;
    padding-right: 12px;
    align-items: flex-end;
    align-self: stretch;
    min-height: var(--st-composer-height);
    flex-wrap: nowrap;
}

#rightSendForm>div:not(.mes_stop) {
    width: 32px;
    height: var(--st-composer-height);
    opacity: 1;
    color: var(--st-muted);
    font-size: 15px;
}

#rightSendForm>div:hover {
    filter: none;
    color: var(--st-text-3);
}

#send_but {
    color: var(--st-accent) !important;
}

#send_but:hover {
    color: var(--st-accent-hover) !important;
}

#mes_stop {
    color: var(--st-danger);
}

/* Quick replies sit above the pill, as chips. */
#qr--bar {
    max-width: min(var(--st-composer-max), var(--sheldWidth));
    margin: 0 auto 10px;
    gap: 6px;
}

#qr--bar .qr--button {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-radius-pill);
    padding: 6px 14px;
    color: var(--st-text-4);
    font-size: calc(var(--mainFontSize) * 0.85);
}

#qr--bar .qr--button:hover {
    background-color: var(--st-selected);
    color: var(--st-text);
}

/* ---------------------------------------------------------------------
   11. Character list page
   ------------------------------------------------------------------ */

#right-nav-panel #rm_print_characters_block {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 14px;
    align-content: start;
    height: auto;
    padding: 8px 2px 24px;
}

.character_select,
.group_select,
.bogus_folder_select {
    background-color: var(--st-well);
    border-radius: var(--st-radius);
    padding: 16px 44px 16px 16px;
    margin-bottom: 0;
    gap: 16px;
    align-items: center;
    transition: background-color var(--animation-duration-2x);
}

.character_select:hover,
.group_select:hover,
.bogus_folder_select:hover {
    background-color: #16161a;
}

.character_select .avatar,
.group_select .avatar,
.bogus_folder_select .avatar {
    width: 52px;
    height: 52px;
    flex: none;
}

.character_select .avatar img,
.group_select .avatar img {
    width: 52px;
    height: 52px;
    border: 0;
    box-shadow: none;
}

.character_name_block .ch_name,
.avatar-container .ch_name {
    font-size: calc(var(--mainFontSize) * 1.13);
    font-weight: 600;
    color: #f0f0f2;
}

.ch_description {
    font-size: calc(var(--mainFontSize) * 0.83);
    color: var(--st-muted);
    margin-top: 2px;
}

.ch_fav_icon {
    filter: none;
    color: #2b2b32;
    font-size: 14px;
}

.character_select.is_fav .ch_fav_icon,
.group_select.is_fav .ch_fav_icon {
    color: #f0c040;
}

.character_select.is_fav .ch_name,
.group_select.is_fav .ch_name,
.group_member.is_fav .ch_name {
    color: #f0f0f2;
}

/* Character portraits read as rounded rectangles in the character panes.
   Chat avatars stay circular, so this is a CSS override rather than the
   avatar_style theme setting, which would change both. */
#rm_print_characters_block .character_select .avatar,
#rm_print_characters_block .character_select .avatar img,
#rm_print_characters_block .group_select .avatar,
#rm_print_characters_block .group_select .avatar img,
#rm_print_characters_block .bogus_folder_select .avatar,
#rm_print_characters_block .bogus_folder_select .avatar img,
#avatar_div_div,
#avatar_load_preview,
#rm_ch_create_block .avatar_div .avatar,
#rm_ch_create_block .avatar_div .avatar img {
    border-radius: 14px;
}

/* The editor's portrait is capped at --avatar-base-width (38px) and squashed
   by .avatar img's fixed dimensions. Character cards are 2:3, so give it a
   real portrait footprint and let the controls take the rest of the row.
   .add_avatar's "border" is a 2px solid rule in the body colour — a white
   ring here — so that goes too. */
#rm_ch_create_block #avatar_div {
    align-items: flex-start;
    gap: 14px;
    flex-wrap: nowrap;
}

#rm_ch_create_block #avatar_div_div {
    flex: 0 0 auto;
    height: 120px;
    width: auto;
    aspect-ratio: 2 / 3;
    margin: 0;
    border: 0;
    padding: 0;
    overflow: hidden;
    border-radius: 14px;
}

#rm_ch_create_block #avatar_load_preview {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;
    border: 0;
    border-radius: 14px;
    box-shadow: none;
}

#rm_ch_create_block #avatar_controls {
    flex: 1 1 auto;
    min-width: 0;
    align-content: flex-start;
}

/* Tags as pills. */
.tag {
    background-color: var(--st-selected);
    border: 0;
    border-radius: var(--st-radius-pill);
    padding: 2px 10px;
    font-size: calc(var(--mainFontSize) * 0.68);
    color: var(--st-text-2);
}

#rm_button_selected_ch h2 {
    font-weight: 300;
    color: var(--st-text-4);
}

/* ---------------------------------------------------------------------
   11b. Backgrounds panel
   ------------------------------------------------------------------ */

/* Five thumbnails across a 452 px sheet is a filmstrip; three is a grid. */
#Backgrounds {
    --bg-thumb-columns: 3;
}

#bg-header-fixed {
    background-color: transparent;
    border-bottom: 0;
    padding: 0 0 10px;
}

/* The control row overflows its container rather than wrapping, which cuts
   the last button off the right edge. */
.bg-header-row-1,
.bg-header-row-2 {
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

#bg-header-fixed .menu_button {
    margin: 0;
}

#background_fitting {
    width: auto;
    flex: 0 1 auto;
}

.bg_example,
.bg_folder_tile {
    border-radius: 14px;
    overflow: hidden;
}

/* ---------------------------------------------------------------------
   11b2. World Info / Lorebooks
   ------------------------------------------------------------------ */

/* This panel assumes a full-width drawer: a two-column header, and a
   floating strip of column titles (#WIEntryHeaderTitlesPC) that only lines
   up with the fields underneath it when the panel is wide. In a 452px sheet
   the two header columns collide and the strip floats free of its columns.

   SillyTavern already has a narrow layout for all of it — it is just gated
   behind the 1000px breakpoint. Run it at every width instead. */

#wiTopBlock,
#wiActivationSettings,
.wi-settings {
    flex-direction: column;
    gap: 8px;
}

#WIMultiSelector {
    align-self: normal;
    width: 100%;
}

/* Column-title strip off; the per-field labels it was standing in for on. */
#WIEntryHeaderTitlesPC {
    display: none;
}

.WIEntryHeaderTitleMobile {
    display: block !important;
}

/* Upstream's own narrow rule says `.WIEntryHeaderControls`, but the element
   in the DOM is `.WIEnteryHeaderControls` — an "Entery" typo in the template
   that has never matched. That is why only half the header ever reflowed.
   Both spellings are listed so this keeps working if upstream fixes it. */
.WIEntryTitleAndStatus,
.WIEntryHeaderControls,
.WIEnteryHeaderControls {
    width: 100%;
}

/* Entry header — title row, then the four controls, then the actions. */
#WorldInfo .world_entry .inline-drawer-header,
#world_popup .world_entry .inline-drawer-header {
    flex-wrap: wrap;
    align-items: center;
    row-gap: 8px;
}

/* The title/status pair and the controls stack instead of competing. */
.world_entry .flex-container:has(> .WIEntryTitleAndStatus) {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
}

.world_entry .WIEntryTitleAndStatus {
    gap: 8px;
    flex-wrap: nowrap;
}

.world_entry .WIEntryTitleAndStatus>.flex-container {
    flex: 1 1 auto;
    min-width: 0;
}

/* The memo field was collapsing to a few characters wide. field-sizing lets
   a long title grow the box instead of hiding behind a scrollbar. */
.world_entry .WIEntryTitleAndStatus textarea[name="comment"] {
    width: 100%;
    min-width: 0;
    margin: 0;
    resize: none;
    field-sizing: content;
    overflow: hidden;
    min-height: var(--st-wi-title-row);
    max-height: 6lh;
}

/* The plaintext/fancy toggle is offset by a label height that this layout
   no longer puts above it; centre it on the field it belongs to. */
.world_entry .switch_input_type_icon {
    margin-top: 0;
    top: auto;
    bottom: 0;
    right: 8px;
    height: 38px;
    display: grid;
    place-items: center;
}

/* Position / Order / Trigger % share one row. Inline labels plus three
   controls need ~380px against the ~334px a 412px card actually offers, so
   the labels sit above their controls in three columns — which is also how
   every other field in this card is labelled. */
.world_entry .WIEnteryHeaderControls,
.world_entry .WIEntryHeaderControls {
    display: grid;
    grid-template-columns: 1.25fr 1fr 1fr;
    align-items: start;
    gap: 4px 10px;
    min-width: 0;
}

/* Equal control heights so the three labels sit on one line. */
.world_entry .WIEnteryHeaderControls select,
.world_entry .WIEnteryHeaderControls input[type="number"],
.world_entry .WIEntryHeaderControls select,
.world_entry .WIEntryHeaderControls input[type="number"] {
    height: 38px;
}

.world_entry .WIEnteryHeaderControls>.world_entry_form_control,
.world_entry .WIEntryHeaderControls>.world_entry_form_control {
    min-width: 0;
}

.world_entry .WIEnteryHeaderControls select[name="position"] {
    width: 100%;
    min-width: 0;
    padding-left: 10px;
    padding-right: 22px;
    background-position: right 8px center;
}

.world_entry .WIEnteryHeaderControls .world_entry_form_control,
.world_entry .WIEntryHeaderControls .world_entry_form_control {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    margin: 0;
    min-width: 0;
}

.world_entry .WIEntryHeaderTitleMobile {
    margin: 0;
    white-space: nowrap;
    color: var(--st-muted);
    font-size: calc(var(--mainFontSize) * 0.76);
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Room for four digits plus the spin buttons Chrome reserves space for,
   trimmed to what a single row can afford. */
.world_entry .WIEnteryHeaderControls input[type="number"],
.world_entry .WIEntryHeaderControls input[type="number"] {
    width: 100%;
    min-width: 0;
    max-width: none;
    padding-left: 10px;
    padding-right: 4px;
    text-align: left;
}

/* Chrome reserves content-box width for the spin buttons whether or not
   they are wanted. These values are typed, and the row needs the pixels. */
.world_entry .WIEnteryHeaderControls input[type="number"]::-webkit-inner-spin-button,
.world_entry .WIEnteryHeaderControls input[type="number"]::-webkit-outer-spin-button,
.world_entry .WIEntryHeaderControls input[type="number"]::-webkit-inner-spin-button,
.world_entry .WIEntryHeaderControls input[type="number"]::-webkit-outer-spin-button {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
}

/* The expanded edit form packs three keyword fields and six override fields
   into single rows. Neither survives sheet width — wrap them. */
.world_entry [name="keywordsAndLogicBlock"],
.world_entry [name="perEntryOverridesBlock"] {
    flex-wrap: wrap;
    gap: 12px;
    align-items: flex-start;
}

.world_entry [name="keywordsAndLogicBlock"]>.world_entry_form_control {
    flex: 1 1 100%;
    min-width: 0;
}

.world_entry [name="keywordsAndLogicBlock"]>.world_entry_form_control:has(select[name="entryLogicType"]) {
    flex: 0 0 auto;
}

.world_entry [name="perEntryOverridesBlock"]>.world_entry_form_control {
    flex: 1 1 45%;
    min-width: 140px;
}

/* The lower half of the entry form is two five- and two-up flex rows sized
   in flex units (flex4 / flex2). At sheet width a "flex2" column lands
   around 60px, which clips its own value — "100" renders as "10". Wrap the
   rows and give the columns a floor. */
.world_entry .flex-container.flexGap10 {
    flex-wrap: wrap;
    gap: 12px;
}

.world_entry .flex-container.flexGap10>* {
    min-width: 0;
}

.world_entry .flex-container.flexGap10>.flex4 {
    flex: 1 1 100%;
}

.world_entry .flex-container.flexGap10>.flex2 {
    flex: 1 1 calc(50% - 6px);
    min-width: 132px;
}

/* The Content caption crams a title, a token count and a stack of four
   toggles onto one nowrap line. Let it wrap; the toggles take their own. */
.world_entry .world_entry_form_control>label>small>.flex-container.flexnowrap {
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: 6px 12px;
}

.world_entry .world_entry_form_control>label>small>.flex-container.flexnowrap>.flex-container {
    width: 100%;
}

/* Nothing in an entry may clip its own value. No text-overflow here: on a
   narrow input[type=number] Chrome reserves room for the spin buttons, so
   an ellipsis kicks in with the value still fitting — "100" became "1…". */
.world_entry .text_pole,
.world_entry input[type="number"],
.world_entry input[type="text"] {
    min-width: 0;
}

/* Field captions read left in a column layout, not centred over nothing. */
.world_entry .world_entry_form_control>small {
    text-align: left;
    color: var(--st-muted);
    font-size: calc(var(--mainFontSize) * 0.78);
    margin-bottom: 4px;
}

/* Depth only applies at position "@D". Upstream disables the input and sets
   visibility:hidden, which in a column layout leaves a dangling "Depth:"
   label over an empty gap. Drop the whole control while it is inert. */
.world_entry .world_entry_form_control:has(> input[name="depth"]:disabled) {
    display: none;
}

/* Chevron, kill switch and the action buttons align to the title row rather
   than floating against the middle of a now two-row block. */
.world_entry .inline-drawer-header {
    align-items: flex-start;
}

/* Stays full width so the four controls have room to flow two-up; the
   action buttons take the row underneath. */
.world_entry .world_entry_thin_controls {
    align-items: flex-start;
}

/* The collapse chevron and the kill switch render at different font sizes
   (11px vs 14.55px), and the chevron also inherits `padding: 12px 0` from
   the inline-drawer-header rule — so equal margins align neither their
   boxes nor, more visibly, their glyph ink. Give both an identical box the
   height of the title row and an identical font size, then centre the glyph
   in it: they line up with each other and sit on the memo's centre line.
   Fixed height on purpose — as the memo grows they stay on its first line
   rather than drifting down with it. */
.world_entry .world_entry_thin_controls>.inline-drawer-toggle,
.world_entry .world_entry_thin_controls>.killSwitch {
    margin-top: 0;
    padding: 0;
    height: var(--st-wi-title-row);
    min-height: var(--st-wi-title-row);
    font-size: 14px;
    line-height: 1;
    display: grid;
    place-items: center;
    flex: none;
    align-self: flex-start;
}

.world_entry .inline-drawer-header>.drag-handle {
    margin-top: 7px;
}

.world_entry .inline-drawer-header>.menu_button {
    margin-top: 0;
    padding: 7px 9px;
}

.world_entry .inline-drawer-header>.menu_button:first-of-type {
    margin-left: auto;
}

/* A collapsed entry should not reserve a screenful of empty card. */
#WorldInfo .world_entry .inline-drawer-content:empty,
#world_popup .world_entry .inline-drawer-content:empty {
    padding: 0;
    min-height: 0;
}

#WorldInfo .wi-card-entry,
#world_popup .wi-card-entry {
    padding: 6px 14px 8px;
}

.WIEntryContentAndMemo {
    flex-flow: column;
}

.WIEntryContentAndMemo .world_entry_thin_controls {
    width: 100%;
}

.world_entry_form_control.world_entry_form_horizontal {
    align-items: flex-start;
    row-gap: 8px;
}

.world_entry_form_control.world_entry_form_horizontal .world_popup_expander {
    display: none;
}

#worldInfoScanningCheckboxes {
    flex-flow: row;
    flex-wrap: wrap;
}

/* Entries as cards, matching the rest of the system. One card per entry:
   .wi-card-entry is it. The .inline-drawer nested inside would otherwise
   pick up the generic card treatment and stack a second surface — and its
   padding — inside the first. */
#WorldInfo .world_entry .inline-drawer,
#world_popup .world_entry .inline-drawer {
    background-color: transparent;
    border-radius: 0;
    padding: 0;
    margin-bottom: 0;
}

#WorldInfo .wi-card-entry,
#world_popup .wi-card-entry {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-radius);
    padding: 6px 14px;
    margin-bottom: 10px;
}

#WorldInfo .world_entry .inline-drawer-header,
#world_popup .world_entry .inline-drawer-header {
    padding: 10px 0;
}

/* Number fields were clipping their own values ("100" showing as "10"). */
.world_entry_form_control input[type="number"],
.world_entry_form_control input.text_pole[type="number"] {
    min-width: 4.5em;
    text-align: left;
}

.world_entry_form_control {
    min-width: 0;
}

/* --- Toolbar ---------------------------------------------------------
   Upstream packs the lorebook picker, five file buttons, five entry
   buttons, a search box, a sort select and the pager into two flex rows.
   At sheet width the picker gets whatever is left over — a sliver too
   narrow to read a single lorebook name, and since a native <select>
   sizes its dropdown to itself, the open list is unreadable too.

   Rebuilt as: picker row, button row, search row. The line breaks are
   forced with full-basis pseudo-elements rather than left to wrapping,
   so the rows hold regardless of how wide the buttons render. */

#world_popup>.flex-container:has(#world_editor_select),
#world_popup>.flex-container:has(#world_info_search) {
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 12px 8px;
    width: 100%;
    margin-bottom: 4px;
}

/* Row 1 — Create or [ picker ] */
#world_create_button {
    order: 1;
    flex: 0 0 auto;
    margin: 0;
}

#world_popup>.flex-container:has(#world_editor_select)>small {
    order: 2;
    color: var(--st-muted);
}

/* select2 replaces the picker with a wrapper span and hides the real
   <select> (position:absolute, .select2-hidden-accessible), so the visible
   control — and the width the dropdown list inherits — is the span. It also
   writes its width as an inline style, hence !important. */
#world_popup>.flex-container:has(#world_editor_select)>.select2-container {
    order: 3;
    flex: 1 1 200px;
    min-width: 200px;
    width: auto !important;
    margin: 0;
}

#world_editor_select {
    order: 3;
}

#world_popup .select2-container .select2-selection--single {
    height: 38px;
    display: flex;
    align-items: center;
}

#world_popup>.flex-container:has(#world_editor_select)::before {
    content: '';
    order: 4;
    flex-basis: 100%;
    height: 0;
}

/* Row 2 — the lorebook file buttons */
#world_import_button,
#world_popup_export,
#world_popup_name_button,
#world_duplicate,
#world_popup_delete {
    order: 5;
    margin: 0;
}

/* Row 3 — the entry buttons, pulled together with refresh */
#world_popup_new,
#OpenAllWIEntries,
#CloseAllWIEntries,
#world_backfill_memos,
#world_apply_current_sorting,
#world_refresh {
    order: 1;
    margin: 0;
}

#world_popup>.flex-container:has(#world_info_search)::before {
    content: '';
    order: 2;
    flex-basis: 100%;
    height: 0;
}

/* Row 4 — search, full width and on its own */
#world_info_search {
    order: 3;
    flex: 1 1 100%;
    width: 100%;
    margin: 0;
}

#world_popup>.flex-container:has(#world_info_search)::after {
    content: '';
    order: 4;
    flex-basis: 100%;
    height: 0;
}

/* Row 5 — sort and pager */
#world_info_sort_order {
    order: 5;
    flex: 0 1 auto;
    width: auto;
    min-width: 140px;
    margin: 0;
}

#world_info_pagination {
    order: 6;
    flex: 1 1 auto;
    justify-content: flex-end;
}

#WorldInfo .world_info_select_block {
    flex-wrap: wrap;
}

/* The activation-settings disclosure sits under its own label, not on it. */
#wiTopBlock .range-block-title {
    width: 100%;
    text-align: left;
    margin-bottom: 6px;
}

#wiTopBlock .inline-drawer {
    width: 100%;
}

/* ---------------------------------------------------------------------
   11c. Zoomed avatar
   ------------------------------------------------------------------ */

/* Upstream parks this in the empty gutter beside the chat and sizes it from
   that gutter's width. This layout has no gutter — the chat fills everything
   right of the rail — so the sum came out at zero and the panel collapsed
   into the corner underneath the rail. Anchor it to the chat area instead.
   No !important on `left`: dragging sets an inline style that must still win. */
.zoomed_avatar {
    --maxWidth: min(calc(90dvh * 0.666), 34vw);
    --leftPosition: calc(var(--st-rail-width) + 18px);
    left: calc(var(--st-rail-width) + 18px);
    /* clear the composer rather than sitting on top of it */
    bottom: 78px;
    width: auto;
    min-width: 220px;
    max-width: var(--maxWidth);
    max-height: calc(100dvh - 96px) !important;
    border: 0;
    border-radius: var(--st-radius);
    overflow: hidden;
    box-shadow: 0 30px 80px -20px rgba(0, 0, 0, .85);
    z-index: 3010;
}

.zoomed_avatar .zoomed_avatar_container {
    width: 100%;
    height: 100%;
}

/* Scale a tall portrait down to fit rather than cropping it. */
.zoomed_avatar .zoomed_avatar_img {
    display: block;
    width: auto;
    height: auto;
    max-width: 100%;
    max-height: calc(100dvh - 96px);
    object-fit: contain;
    border: 0;
    border-radius: 0;
    box-shadow: none;
}

.zoomed_avatar .panelControlBar {
    background-color: rgba(8, 8, 10, .6);
    border-radius: var(--st-radius-xs);
    padding: 2px;
}

@media screen and (max-width: 1000px) {
    .zoomed_avatar {
        --maxWidth: min(calc(70dvh * 0.666), 80vw);
        --leftPosition: 12px;
        left: 12px;
        bottom: calc(var(--st-bar-height) + 12px);
        max-height: calc(100dvh - var(--st-bar-height) - 24px) !important;
    }

    .zoomed_avatar .zoomed_avatar_img {
        max-height: calc(100dvh - var(--st-bar-height) - 24px);
    }
}

/* ---------------------------------------------------------------------
   12. Popups and menus
   ------------------------------------------------------------------ */

.popup,
#shadow_popup .popup,
dialog.popup {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-radius);
    box-shadow: 0 30px 80px -20px rgba(0, 0, 0, .85);
    color: var(--st-text-2);
}

/* Advanced Definitions. Sized in the desktop block; skinned here so the
   mobile full-bleed version gets the same surface. */
#character_popup {
    background-color: var(--st-sheet);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    border: 0;
    border-radius: var(--st-radius);
    box-shadow: 0 30px 80px -20px rgba(0, 0, 0, .85);
    padding: 24px 28px;
}

/* The "large editor" (the maximize icon on any big text field) opens as a
   popup with { wide: true, large: true }. .wide_dialogue_popup sets
   `min-width: var(--sheldWidth)` — which this theme sets to 100vw — so it
   swallows the screen. Size it like Advanced Definitions instead.

   Centred with insets rather than a transform: the open animation is a
   scaleY keyframe, and a translate here would snap once it finished. */
.popup.wide_dialogue_popup,
.popup.large_dialogue_popup {
    min-width: 0;
}

.popup.large_dialogue_popup {
    height: calc(100dvh - 48px) !important;
    max-height: calc(100dvh - 48px) !important;
}

.popup.wide_dialogue_popup .popup-body,
.popup.large_dialogue_popup .popup-body {
    max-height: none;
}

.popup::backdrop,
#shadow_popup {
    background-color: rgba(4, 4, 6, .72);
    backdrop-filter: none;
}

.popup .popup-button-ok,
.popup .popup-button-close {
    background-color: var(--st-accent-solid);
    color: #e6e9f7;
}

#options .options-content,
.list-group,
.autoComplete,
#context_menu,
#character_context_menu ul {
    background-color: var(--st-card);
    border: 0;
    border-radius: var(--st-radius-sm);
    box-shadow: 0 18px 50px -14px rgba(0, 0, 0, .8);
    padding: 6px;
}

#options .options-content a,
#character_context_menu li button {
    border-radius: var(--st-radius-xs);
    color: var(--st-text-3);
    padding: 9px 12px;
}

#options .options-content a:hover,
#character_context_menu li button:hover {
    background-color: var(--st-inset);
    color: var(--st-text);
}

/* ---------------------------------------------------------------------
   13. Third-party widgets
   ------------------------------------------------------------------ */

/* select2 */
.select2-container--default .select2-selection--multiple,
.select2-container--default .select2-selection--single,
.select2-dropdown,
.select2-container--default .select2-search--dropdown .select2-search__field {
    background-color: var(--st-inset) !important;
    border: 0 !important;
    border-radius: var(--st-radius-sm) !important;
    color: var(--st-text-2) !important;
}

.select2-container--default .select2-results__option {
    background-color: var(--st-card);
    color: var(--st-text-3);
}

.select2-container--default .select2-results__option--highlighted[aria-selected],
.select2-container--default .select2-results__option--selected {
    background-color: var(--st-selected) !important;
    color: var(--st-text) !important;
}

.select2-container--default .select2-selection--multiple .select2-selection__choice {
    background-color: var(--st-selected) !important;
    border: 0 !important;
    border-radius: var(--st-radius-pill) !important;
    color: var(--st-text-2) !important;
    padding: 2px 10px !important;
}

/* toastr */
#toast-container>div {
    background-color: var(--st-card) !important;
    border: 0 !important;
    border-radius: var(--st-radius-sm) !important;
    box-shadow: 0 18px 50px -14px rgba(0, 0, 0, .8) !important;
    color: var(--st-text-2) !important;
    opacity: 1 !important;
}

#toast-container>div .toast-title {
    color: var(--st-text);
}

/* jQuery UI */
.ui-widget-content,
.ui-dialog,
.ui-autocomplete {
    background: var(--st-card) !important;
    border: 0 !important;
    border-radius: var(--st-radius-sm) !important;
    color: var(--st-text-2) !important;
}

.ui-widget-header,
.ui-dialog-titlebar {
    background: var(--st-card) !important;
    border: 0 !important;
    color: var(--st-text-4) !important;
}

.ui-state-default,
.ui-state-hover,
.ui-menu-item-wrapper.ui-state-active {
    background: var(--st-selected) !important;
    border: 0 !important;
    color: var(--st-text) !important;
}

/* cropper */
.cropper-view-box,
.cropper-line,
.cropper-point {
    background-color: var(--st-accent);
}

/* toolcool-color-picker renders in a shadow root: set variables, not
   descendant selectors. */
toolcool-color-picker {
    --tool-cool-color-picker-btn-bg: var(--st-inset);
    --tool-cool-color-picker-btn-border-color: transparent;
    --tool-cool-color-picker-bg: var(--st-card);
    --tool-cool-color-picker-text-color: var(--st-text-2);
    --tool-cool-color-picker-border-color: transparent;
    border-radius: var(--st-radius-xs);
    overflow: hidden;
}

/* ---------------------------------------------------------------------
   14. Mobile — rail becomes a bottom bar, sheets become bottom sheets
   ------------------------------------------------------------------ */

@media screen and (max-width: 1000px) {

    #top-settings-holder {
        position: fixed;
        top: auto;
        bottom: 0;
        left: 0;
        right: 0;
        width: 100%;
        height: var(--st-bar-height);
        margin: 0;
        padding: 0 6px env(safe-area-inset-bottom, 6px);
        flex-direction: row;
        align-items: center;
        justify-content: space-around;
        gap: 2px;
        overflow-x: auto;
        background-color: var(--st-sheet);
        z-index: 3005;
    }

    #top-settings-holder>.drawer {
        width: auto;
        flex: none;
    }

    /* Nine slots have to fit a 390 px phone: shrink rather than overflow. */
    #top-settings-holder .drawer-icon {
        width: min(44px, 10vw);
        height: 44px;
        font-size: 16px;
    }

    /* A 20px touch thumb overhangs ~10px above the track, and at high values
       it sits directly under the right-aligned number. Buy it clearance. */
    .drawer-content :has(> .neo-range-slider) {
        row-gap: 20px !important;
        margin-bottom: 26px;
    }

    /* mobile-styles.css pins these panels with `top: ... !important`, so the
       bottom-sheet anchor has to answer in kind. */
    /* Full height, not a 72dvh sheet: SillyTavern's panels carry far too many
       controls to spend a quarter of a phone screen on the chat behind them.
       The bottom bar is the only thing kept clear. */
    #top-settings-holder .drawer-content,
    #left-nav-panel,
    #right-nav-panel,
    #WorldInfo,
    #floatingPrompt,
    #cfgConfig,
    #logprobsViewer {
        top: 0 !important;
        bottom: var(--st-bar-height) !important;
    }

    #top-settings-holder .drawer-content {
        position: fixed;
        left: 0;
        right: 0;
        bottom: var(--st-bar-height);
        top: auto;
        width: 100%;
        min-width: 0;
        max-width: none;
        max-height: 80dvh;
        margin: 0;
        padding: 46px 16px 0;
        border: 0;
        border-radius: 0;
        background-color: var(--st-sheet);
        box-shadow: 0 -20px 60px -20px rgba(0, 0, 0, .85);
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        z-index: 3000;
    }

    /* Bottom bar paints above the sheets sliding up past it. */
    #top-settings-holder::before {
        content: '';
        position: fixed;
        top: auto;
        left: 0;
        right: 0;
        bottom: 0;
        width: 100%;
        height: var(--st-bar-height);
        background-color: var(--st-sheet);
        z-index: 3001;
        pointer-events: none;
    }

    #top-settings-holder .drawer-toggle {
        position: relative;
        z-index: 3002;
    }

    /* Bottom sheets come in from the bottom, for the same reason. */
    #top-settings-holder .drawer-content {
        transform: translateY(100%);
        opacity: 0;
        transition-property: transform, opacity, display;
        transition-duration: var(--animation-duration-2x);
        transition-timing-function: ease;
        transition-behavior: allow-discrete;
    }

    #top-settings-holder .drawer-content.openDrawer {
        transform: translateY(0);
        opacity: 1;
    }

    @starting-style {
        #top-settings-holder .drawer-content.openDrawer {
            transform: translateY(100%);
            opacity: 0;
        }
    }

    /* An explicit height, not auto: .scrollableInner is height:100%, so an
       auto-height sheet resolves to nothing and collapses to its min-height. */
    #top-settings-holder .drawer-content.openDrawer {
        display: flex;
        flex-direction: column;
        height: calc(100dvh - var(--st-bar-height));
        max-height: calc(100dvh - var(--st-bar-height));
    }

    .topRightInset {
        top: 12px;
        right: 14px;
    }

    #clickSlidersTips,
    .editable-slider-notification {
        top: 18px;
        left: 16px;
        right: 58px;
    }

    #sheld {
        left: 0;
        right: 0;
        top: 0;
        width: 100dvw;
        height: calc(100dvh - var(--st-bar-height));
        max-height: calc(100dvh - var(--st-bar-height));
    }

    #chat {
        padding: 12px 14px 18px;
    }

    #form_sheld {
        padding: 0 14px 10px;
    }

    /* Touch targets: 44px minimum, fatter slider tracks and thumbs. */
    input[type="range"],
    .neo-range-slider {
        height: 6px !important;
    }

    input[type="range"]::-webkit-slider-thumb,
    .neo-range-slider::-webkit-slider-thumb {
        width: 18px;
        height: 18px;
    }

    input[type="range"]::-moz-range-thumb,
    .neo-range-slider::-moz-range-thumb {
        width: 18px;
        height: 18px;
    }

    #right-nav-panel #rm_print_characters_block {
        grid-template-columns: 1fr;
    }

    /* --- No horizontal scrolling, anywhere ---------------------------
       Content wraps or clips; it never asks for a sideways scrollbar. */

    html,
    body {
        overflow-x: hidden;
        max-width: 100dvw;
    }

    #sheld,
    #chat,
    #form_sheld,
    #top-settings-holder,
    .drawer-content,
    #character_popup,
    .popup {
        max-width: 100dvw;
    }

    /* Every pane that could scroll sideways clips instead.

       NOT .mes / .mes_block / .mes_text. Setting overflow-x on a flex item
       makes it a scroll container, which drops its automatic min-height
       floor — so in #chat's flex column every message shrinks. With a long
       chat they compress to ~10px and the conversation vanishes. #chat
       clips at the pane level, so they gain nothing anyway. */
    #chat,
    #sheld,
    .drawer-content,
    .scrollableInner,
    .scrollableInnerFull,
    #rm_print_characters_block,
    #world_popup_entries_list,
    #rm_ch_create_block {
        overflow-x: hidden;
    }

    /* And messages hold their height regardless. */
    #chat>.mes {
        flex-shrink: 0;
    }

    /* A flex or grid child that refuses to shrink is what makes its parent
       wider than the screen in the first place. */
    .drawer-content .flex-container>*,
    #rm_print_characters_block>*,
    .mes_block>*,
    .character_select>*,
    .group_select>* {
        min-width: 0;
    }

    /* Long words, code and tables wrap rather than demanding a scrollbar. */
    .mes_text,
    .mes_text p,
    .mes_text li,
    .mes_reasoning {
        overflow-wrap: break-word;
    }

    .mes_text pre,
    .mes_text code,
    .drawer-content pre,
    .drawer-content code {
        white-space: pre-wrap;
        overflow-wrap: break-word;
        word-break: break-word;
    }

    .mes_text table {
        table-layout: fixed;
        width: 100%;
    }

    .mes_text td,
    .mes_text th {
        overflow-wrap: break-word;
    }

    /* A modal <dialog> centres itself with `margin: auto`, so shrinking the
       height alone still leaves it overlapping the bottom bar. A fixed
       bottom margin against an auto top margin lifts it clear. */
    .popup.wide_dialogue_popup,
    .popup.large_dialogue_popup {
        width: calc(100dvw - 24px);
        max-width: calc(100dvw - 24px) !important;
        height: calc(100dvh - var(--st-bar-height) - 36px) !important;
        max-height: calc(100dvh - var(--st-bar-height) - 36px) !important;
        margin-bottom: var(--st-bar-height);
    }

    /* The recent-chat row squeezes the chat name down to ~46px and ellipses
       almost all of it. Give it the row. */
    .welcomeRecent .recentChatList .recentChat .chatNameContainer {
        flex-wrap: wrap;
    }

    .welcomeRecent .recentChatList .recentChat .chatName {
        flex: 1 1 100%;
        min-width: 0;
    }
}
